const upsertReportFeedback = `-- name: UpsertReportFeedback :execrows
INSERT INTO report_feedback (report_id, user_id, rating, reasons, comment)
SELECT r.id, r.user_id, $3, $4, $5 FROM reports r WHERE r.id = $1 AND r.user_id = $2
ON CONFLICT (report_id) DO UPDATE SET
    rating = excluded.rating, reasons = excluded.reasons, comment = excluded.comment, updated_at = now()
`

type UpsertReportFeedbackParams struct {
	ID      uuid.UUID
	UserID  uuid.UUID
	Rating  string
	Reasons []string
	Comment string
}

func (q *Queries) UpsertReportFeedback(ctx context.Context, arg UpsertReportFeedbackParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertReportFeedback,
		arg.ID,
		arg.UserID,
		arg.Rating,
		arg.Reasons,
		arg.Comment,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
